import{_ as n,o as a,c as s,a2 as r}from"./chunks/framework.DbIb1qZn.js";const p=JSON.parse(`{"title":"What's New","description":"A plain-language summary of what each Frensense version added.","frontmatter":{"title":"What's New","description":"A plain-language summary of what each Frensense version added."},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md"}`),o={name:"whats-new.md"};function t(i,e,l,c,d,g){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-new-in-frensense" tabindex="-1">What&#39;s New in Frensense <a class="header-anchor" href="#what-s-new-in-frensense" aria-label="Permalink to &quot;What&#39;s New in Frensense&quot;">​</a></h1><p>A quick look at what changed in each release, written for everyone — no compiler knowledge required.</p><hr><h2 id="_0-8-1-—-scan-progress" tabindex="-1">0.8.1 — Scan Progress <a class="header-anchor" href="#_0-8-1-—-scan-progress" aria-label="Permalink to &quot;0.8.1 — Scan Progress&quot;">​</a></h2><p><strong>You can now watch Frensense work.</strong></p><p>Before this release, running a scan showed the header and then went quiet until it finished. That silence made it hard to tell whether the scan was progressing or stuck.</p><p>Starting with 0.8.1:</p><ul><li><strong>In your terminal</strong>, a live progress bar updates as each file is processed. It shows the current phase (lowering files, then analyzing the program), how many files have been scanned out of the total, any errors encountered, and how much memory is in use.</li><li><strong>In CI or when piping output</strong>, clean log lines appear at regular milestones so your pipeline logs stay readable without any special terminal codes.</li><li><strong>In machine-output modes</strong> (<code>--json</code>, <code>--sarif</code>), nothing changes — structured output goes to stdout untouched; progress goes to stderr.</li><li>Use <code>--no-progress</code> to suppress all progress output if you prefer silence.</li></ul><p>The scan summary at the end also now shows <strong>Peak Memory (RSS)</strong> and a <strong>Files Scanned</strong> count.</p><hr><h2 id="_0-8-0-—-package-aware-scanning-and-ai-agents" tabindex="-1">0.8.0 — Package-Aware Scanning and AI Agents <a class="header-anchor" href="#_0-8-0-—-package-aware-scanning-and-ai-agents" aria-label="Permalink to &quot;0.8.0 — Package-Aware Scanning and AI Agents&quot;">​</a></h2><p><strong>Fewer false positives. Built-in AI agent support.</strong></p><p>Frensense 0.8.0 was a major release focused on accuracy and integration:</p><ul><li><strong>Package-scoped facts</strong> — rules now understand which library a call belongs to, so a <code>.query()</code> on a harmless UI library no longer triggers the same finding as one on a database driver.</li><li><strong>MCP server</strong> — Frensense ships a built-in Model Context Protocol server so AI coding agents can run security scans directly without shell commands.</li><li><strong>Diff-only mode</strong> — scan only the files changed in a pull request, not the whole codebase.</li><li><strong>Baseline suppression</strong> — accept known findings and only alert on new ones.</li><li><strong>Hidden source directory scanning</strong> — <code>.vitepress</code> and similar dot-prefixed source trees are now scanned alongside regular source files.</li></ul><hr><h2 id="_0-7-0-—-compiler-mode-engine" tabindex="-1">0.7.0 — Compiler-Mode Engine <a class="header-anchor" href="#_0-7-0-—-compiler-mode-engine" aria-label="Permalink to &quot;0.7.0 — Compiler-Mode Engine&quot;">​</a></h2><p><strong>Exact taint paths across functions and files.</strong></p><p>Frensense 0.7.0 rewrote the engine to treat code like a compiler does:</p><ul><li>Every file is lowered to a program graph (IR + SSA form) before analysis.</li><li>Findings include the full source-to-sink path, not just a flagged line.</li><li>Language knowledge (sinks, sanitizers, guards) is separated from the engine and stored in teachable <code>.frc</code> bundles.</li><li>Initial language support: TypeScript, JavaScript, Python, Go, Rust, and C.</li></ul>',19)])])}const u=n(o,[["render",t]]);export{p as __pageData,u as default};
